import{_ as r,o as l,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const S=JSON.parse('{"title":"Unicorn Overlord (2024) — 게임 로직 백과사전","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Ref-Unicorn-Overlord.md","filePath":"rules/Ref-Unicorn-Overlord.md"}'),i={name:"rules/Ref-Unicorn-Overlord.md"};function d(e,t,n,s,h,u){return l(),o("div",null,[...t[0]||(t[0]=[a('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p></div><blockquote><p>출처 인계: <a href="https://github.com/islee23520/seoul-kenshi/blob/docs/reference-context-sync-st_01a079f1/.omo/research/README.md" target="_blank" rel="noreferrer">공유 조사 색인</a>. 로컬 sources.json·원문 패킷 언급은 조사 당시 기록이며 이 전달에 원시 자료가 포함된다는 뜻이 아니다. 누락된 ID는 미확인으로 남긴다. 자동 생성 문서입니다 — 원본은 저장소 내부 조사 문서(<code>unicorn-overlord.md</code>)에서 파생했으며 금지 용어는 위키 공개 기준에 맞게 치환했다.</p></blockquote><h1 id="unicorn-overlord-2024-—-게임-로직-백과사전" tabindex="-1">Unicorn Overlord (2024) — 게임 로직 백과사전 <a class="header-anchor" href="#unicorn-overlord-2024-—-게임-로직-백과사전" aria-label="Permalink to &quot;Unicorn Overlord (2024) — 게임 로직 백과사전&quot;">​</a></h1><blockquote><p>Vanillaware / ATLUS, 2024. PS5·PS4·Xbox·Switch·PC. 판타지 대륙 페브리스에서 제국 제노이라에 점령된 코르니아 왕국을 해방하는 부대 단위 시뮬레이션 RPG. 본편 2024년판 기준, DLC 및 모드 제외.</p><p><strong>출처 표기</strong>: [S-01]~[S-13]은 문서 말미 출처 목록 참조. [문서]=열람한 공식/위키 자료, [추론]=자료 종합 구조 해석, [미확인]=이번 조사에서 확인 못함.</p></blockquote><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><ul><li><strong>장르</strong>: 오거 배틀 계보의 실시간 부대 이동 + 자동 교전 SRPG. 개별 유닛을 턴마다 조작하는 FE/FFT와 달리, 플레이어는 교전 <strong>이전</strong>의 편성·조건 설정과 교전 <strong>외부</strong>의 부대 지휘를 담당한다 [S-11][추론].</li><li><strong>핵심 특징(설계 철학)</strong>: <ol><li><strong>개인 행동의 조건문화</strong>: 개인 스킬 사용은 우선순위 있는 조건부 설정(Tactics)으로 사전에 프로그래밍되고 교전 중엔 자동 실행된다 [S-01][S-08][문서].</li><li><strong>해방이 성장 동력</strong>: 적 점령지를 해방하면 시설·모집·명성이 열린다 [S-11][문서].</li><li><strong>3가지 플레이 표면</strong>: 여행 필드(탐색/대화/채집) → 작전 스테이지(실시간 부대 운용) → 자동 교전(편성·작전의 검증) [S-11][문서/추론].</li><li><strong>부대 조합이 곧 전술</strong>: 클래스 상성·전후열·리더 효과·어시스트의 조합이 승패를 결정 [S-02][S-11][문서/추론].</li></ol></li><li><strong>서사 전제</strong>: 주인공 알레인이 유년기 피난 후 왕위 계승 반지를 받고 코르니아 해방군을 일으켜 제노이라 황제 갈레리우스와 그래코린 대전투로 진행. 최종 결전 분기(스칼렛 구출 여부, 반지 강화 여부, 현자 협력 여부)에 따라 후일담 기록이 달라진다 [S-09][문서].</li></ul><h2 id="_2-코어-루프" tabindex="-1">2. 코어 루프 <a class="header-anchor" href="#_2-코어-루프" aria-label="Permalink to &quot;2. 코어 루프&quot;">​</a></h2><ol><li><strong>여행 필드 탐색</strong>: 알레인으로 마을·요새·채집점 방문, 인물 대화, 퀘스트 수주 [S-11][문서]</li><li><strong>작전 스테이지</strong>: 최대 10개 부대를 실시간(일시정지 가능)으로 이동·출격·점령 지휘. 제한시간 존재(평균 3~5분) [S-01][문서]</li><li><strong>부대 접촉 → 자동 교전</strong>: 양측 부대가 근접하면 행동속도(Initiative) 순 자동 전투. 편성·장비·Tactics가 곧 입력이다 [S-01][S-08][문서]</li><li><strong>전과 수집</strong>: 격파·해방으로 Valor(브레이브) 축적, 퀘스트·재건으로 명성·훈장·골드 획득 [S-04][S-11][문서]</li><li><strong>조직 재투자</strong>: 훈장으로 부대 확장·승격·용병 고용 → 다음 스테이지 [S-03][S-04][S-05][문서]</li></ol><p>결정 지점은 두 곳: <strong>스테이지 중</strong>(어디에 출격하고 누굴 지원할지)과 <strong>스테이지 밖</strong>(훈장을 어디에 쓸지) [추론].</p><h2 id="_3-진행-구조" tabindex="-1">3. 진행 구조 <a class="header-anchor" href="#_3-진행-구조" aria-label="Permalink to &quot;3. 진행 구조&quot;">​</a></h2><ul><li><strong>대륙 5개국 순차 해방</strong>: 코르니아(시작국) → 드라켄홀드 → 엘하임 → 바스토리아스 → 알비온 [S-02][S-07][문서].</li><li><strong>명성(Renown) 등급이 진행의 뼈대</strong>: E→D→C→B→A→S. 퀘스트·마을 재건으로 누적.</li></ul><table tabindex="0"><thead><tr><th>등급</th><th>필요 누적치</th><th>해금</th></tr></thead><tbody><tr><td>E</td><td>0</td><td>기본</td></tr><tr><td>D</td><td>120</td><td>부대 수 3개까지 확장, 요새 용병 고용</td></tr><tr><td>C</td><td>450</td><td>부대 수 4개, 부대 인원 4명</td></tr><tr><td>B</td><td>1750</td><td>클래스 승격</td></tr><tr><td>A</td><td>3000</td><td>부대 인원 5명</td></tr><tr><td>S</td><td>5000</td><td>퀘스트 &quot;왕가의 영묘&quot; 해금</td></tr></tbody></table><p>전투 보상 골드·훈장·명성 배율도 등급마다 상승(E=100% 기준 → S=200%) [S-04][문서].</p><ul><li><strong>부대 수·인원 확장은 훈장 소비</strong>: 시작 3부대×2인. 10부대×5인까지 확장 가능 [S-05][문서].</li><li><strong>투기장(콜리세움)</strong>: 드라켄홀드 바움라테의 아레나. 별도 랭크전으로 동료 영입·전리품 교환 [S-10][문서].</li></ul><h2 id="_4-경제-시스템" tabindex="-1">4. 경제 시스템 <a class="header-anchor" href="#_4-경제-시스템" aria-label="Permalink to &quot;4. 경제 시스템&quot;">​</a></h2><h3 id="_4-1-통화-4종" tabindex="-1">4.1 통화 4종 <a class="header-anchor" href="#_4-1-통화-4종" aria-label="Permalink to &quot;4.1 통화 4종&quot;">​</a></h3><table tabindex="0"><thead><tr><th>통화</th><th>획득</th><th>용도</th></tr></thead><tbody><tr><td>골드(G)</td><td>전투·퀘스트·판매</td><td>무기·소모품 구입</td></tr><tr><td>훈장(Honors)</td><td>퀘스트·납품·전투 보상</td><td>부대 슬롯/인원 확장, 용병 고용, 클래스 승격</td></tr><tr><td>천조각(Divine Shards)</td><td>채집·보물</td><td>교환소</td></tr><tr><td>콜리세움 코인</td><td>투기장</td><td>투기장 상품</td></tr></tbody></table><p>[문서: S-03, S-04, S-05, S-10, S-12]</p><h3 id="_4-2-승격-비용-훈장-s-03-문서" tabindex="-1">4.2 승격 비용 (훈장) [S-03][문서] <a class="header-anchor" href="#_4-2-승격-비용-훈장-s-03-문서" aria-label="Permalink to &quot;4.2 승격 비용 (훈장) [S-03][문서]&quot;">​</a></h3><ul><li>하급 → 상급: 대부분 25~35 (파이터→뱅가드 25, 나이트→그레이트 나이트 35)</li><li>고유 클래스: 로드→하이로드, 프리스테스→하이프리스테스, 크루세이더→발키리 50</li><li>승격 효과: 스탯 상승 + 신스틸 습득 + 기본 AP/PP <strong>영구 증가</strong>. 명성 B 이상 필요</li></ul><h3 id="_4-3-물자-납품·재건" tabindex="-1">4.3 물자 납품·재건 <a class="header-anchor" href="#_4-3-물자-납품·재건" aria-label="Permalink to &quot;4.3 물자 납품·재건&quot;">​</a></h3><p>해방한 마을에 자재(목재·광석·약초·어획)를 납품해 시설을 복구하고 명성을 얻는다. 여관·대장간·상점이 재건되면 파티(친밀도)·장비·물품 접근이 넓어진다 [S-11][문서].</p><h2 id="_5-캐릭터-파티-시스템" tabindex="-1">5. 캐릭터/파티 시스템 <a class="header-anchor" href="#_5-캐릭터-파티-시스템" aria-label="Permalink to &quot;5. 캐릭터/파티 시스템&quot;">​</a></h2><h3 id="_5-1-부대-unit-구조-s-01-s-05-s-11-문서" tabindex="-1">5.1 부대(Unit) 구조 [S-01][S-05][S-11][문서] <a class="header-anchor" href="#_5-1-부대-unit-구조-s-01-s-05-s-11-문서" aria-label="Permalink to &quot;5.1 부대(Unit) 구조 [S-01][S-05][S-11][문서]&quot;">​</a></h3><ul><li>최대 <strong>10부대 × 5인</strong>. 편성판은 전열 3칸 + 후열 3칸. 시작은 3부대 × 2인</li><li><strong>리더가 이동을 결정</strong>: 이동 타입(기병/보병/비행), 스태미나, 리더 효과(Flight=지형 무시, Quick Rest, Barrier Breaker 등)는 리더 클래스 기준. 이동속도는 부대원 전원 기반 → 최강 개인이 최적 리더가 아님</li><li><strong>클래스 계열</strong>(약 25+ 상급 포함): <ul><li>코르니아/드라켄홀드: 파이터·솔저·하우스칼·소드파이터·호플라이트·글래디에이터·워리어·헌터·시프·나이트·래디언트/다크 나이트·클레릭·위저드·위치·샤먼·와이번/그리핀 나이트 + 각 상급</li><li>엘하임: 엘븐 펜서·엘븐 아처(고유: 아우구르/시빌)</li><li>바스토리아스: 웨어울프·웨어폭스·웨어베어·웨어아울(고유: 웨어라이온·스노우 레인저) — 공통 Nightwalk</li><li>알비온: 페더소드·페더보우·페더스태프·페더실드(천사형, Flight) + 프리스테스</li><li>고유: 로드(알레인), 크루세이더(버지니아), 팔라딘(요제프), 프린스(길버트), 드레드노트(아말리아) 등</li></ul></li></ul><h3 id="_5-2-클래스-상성의-대표-축-s-02-문서" tabindex="-1">5.2 클래스 상성의 대표 축 [S-02][문서] <a class="header-anchor" href="#_5-2-클래스-상성의-대표-축-s-02-문서" aria-label="Permalink to &quot;5.2 클래스 상성의 대표 축 [S-02][문서]&quot;">​</a></h3><ul><li>파이터 &gt; 헌터(방어) / 워리어·마법에 약</li><li>솔저 &gt; 기병 / 호플라이트·파이터에 약</li><li>워리어 &gt; 호플라이트·파이터 / 시프·글래디에이터에 약</li><li>헌터 &gt; 비행 / 파이터·호플라이트에 약</li><li>시프: 회피 기반. 정밀명중(Truestrike) 계열에 취약</li><li>나이트 &gt; 보병 / 비행·고회피에 약</li><li>래디언트 나이트 &gt; 캐스터(마법 장벽) / 비행에 약</li><li>비행(그리핀·와이번) &gt; 기병 / 활·캐스터에 약</li><li>&quot;보병&gt;기병&gt;비행&gt;궁수/보병…&quot;의 원환 상성 + 마법/물리 방어 축이 교차 [추론]</li></ul><h3 id="_5-3-모집-경로-s-11-문서" tabindex="-1">5.3 모집 경로 [S-11][문서] <a class="header-anchor" href="#_5-3-모집-경로-s-11-문서" aria-label="Permalink to &quot;5.3 모집 경로 [S-11][문서]&quot;">​</a></h3><ul><li>서사 동료 / 퀘스트·전장 대화 조건부 영입(예: 힐다는 프림 대화 후) / 초반 처분의 지연 효과(가멜 석방 여부) / 투기장 최종 랭크 / 요새의 범용 용병 고용(훈장 지불)</li><li>공식 소개 60명 이상 고유 인물. 리뷰 64명, 한국 위키 최대 71명 — 집계 경계 달라 전수 확정 보류 [S-11][문서]</li></ul><h3 id="_5-4-친밀도-rapport" tabindex="-1">5.4 친밀도(Rapport) <a class="header-anchor" href="#_5-4-친밀도-rapport" aria-label="Permalink to &quot;5.4 친밀도(Rapport)&quot;">​</a></h3><p>여관 등에서 파티 숙박으로 친밀도 상승 → 대화·보상·편성 시너지 [S-11][문서].</p><h2 id="_6-전투-시스템" tabindex="-1">6. 전투 시스템 <a class="header-anchor" href="#_6-전투-시스템" aria-label="Permalink to &quot;6. 전투 시스템&quot;">​</a></h2><h3 id="_6-1-교전-규칙-s-01-s-08-s-11-문서" tabindex="-1">6.1 교전 규칙 [S-01][S-08][S-11][문서] <a class="header-anchor" href="#_6-1-교전-규칙-s-01-s-08-s-11-문서" aria-label="Permalink to &quot;6.1 교전 규칙 [S-01][S-08][S-11][문서]&quot;">​</a></h3><ul><li>부대 접촉 시 자동 교전. <strong>행동속도(Initiative) 순</strong>으로 행동</li><li><strong>AP(행동 포인트)</strong>: 능동 스킬 비용. <strong>PP(패시브 포인트)</strong>: 조건 반응 스킬 비용. AP 소진 또는 한쪽 전멸로 종료</li><li>시간 종료 시 잔여 HP <strong>비율</strong>로 승패 판정(절대치 합계가 아님)</li><li>스태미나: 교전 1회당 1 소비, 0이면 이동 불가. 요새·거점에서 휴식 회복 [S-11][문서/충돌 기록]</li></ul><h3 id="_6-2-tactics-행동-프로그래밍-s-08-문서" tabindex="-1">6.2 Tactics = 행동 프로그래밍 [S-08][문서] <a class="header-anchor" href="#_6-2-tactics-행동-프로그래밍-s-08-문서" aria-label="Permalink to &quot;6.2 Tactics = 행동 프로그래밍 [S-08][문서]&quot;">​</a></h3><ul><li>능동 예: Lean Edge(명중 시 HP 25% 회복), Smash(대상 물리방어 −20%), Heal(HP 75% 미만 아군), Long Thrust(열 관통, 기병 +50 위력)</li><li>패시브 예: Heavy Cover(후열 우선 아군 방호), Arrow Cover(원거리 물리 무효), Pursuit(아군 공격 후 추격), Parting Blow(교전 종료 시 공격)</li><li>발동 조건·우선순위를 플레이어가 사전 편집. 장비가 스킬을 추가하므로 장비 교체=행동 규칙 교체</li><li>어시스트: 원거리·마법·회복·저항 리더 효과를 가진 인접 부대가 교전에 지원 사격/치유 [S-02][문서]</li></ul><h3 id="_6-3-스테이지-운용-s-01-문서" tabindex="-1">6.3 스테이지 운용 [S-01][문서] <a class="header-anchor" href="#_6-3-스테이지-운용-s-01-문서" aria-label="Permalink to &quot;6.3 스테이지 운용 [S-01][문서]&quot;">​</a></h3><ul><li>출격은 통제 거점 반경 내 + Valor 비용. 웨이포인트로 우회 경로 지정, 다중 부대 그룹 지정 가능</li><li><strong>Valor(브레이브) 스킬</strong>: 부대 출격 자체와 필드형 스킬(버프·부활 등)에 소비. 격파·해방으로 축적</li><li>승리 조건은 스테이지마다 상이(점령, 방어, 호위 등) + 실시간 제한</li></ul><h2 id="_7-지도-세계-구조" tabindex="-1">7. 지도/세계 구조 <a class="header-anchor" href="#_7-지도-세계-구조" aria-label="Permalink to &quot;7. 지도/세계 구조&quot;">​</a></h2><ul><li><strong>여행 필드(월드맵)</strong>: 대륙 페브리스 전체를 알레인이 직접 이동해 탐색. 낮/밤 실시간 시계 — 시간대별 인물 배치·시설 이용이 달라진다 [S-11][문서].</li><li><strong>지점 유형</strong> [S-06][S-07][문서]: <ul><li>마을/도시(해방 대상): 상점·여관·재건. 규모 구분(항만/마을/촌락/성벽도시/수도)</li><li>요새(Fort): 부대 확장·용병 고용·해고·모의전·승격의 <strong>조직 관리 허브</strong></li><li>채집점: 광석·목재·약초·어획</li></ul></li><li><strong>작전 스테이지</strong>: 필드 위 특정 지점에서 시작되는 개별 전장. 필드 1 + 스테이지 1의 <strong>2종 논리 표면</strong> + 교전 표현이 세 번째 [S-11][문서/추론].</li><li><strong>해방의 연쇄</strong>: 점령 해방 → 시설 사용 → 자재 납품/복구 → 수비병 지정 → 채집 회수. 수비병으로 지정해도 출격 가능. 해방 마을 재습격은 없다 [S-11][문서].</li></ul><h2 id="_8-외교-세력" tabindex="-1">8. 외교/세력 <a class="header-anchor" href="#_8-외교-세력" aria-label="Permalink to &quot;8. 외교/세력&quot;">​</a></h2><ul><li><strong>세력 구도는 정적</strong>: 플레이어 진영(코르니아 해방군) vs 제노이라 제국의 단순 대립. 동적 국가 AI 없음 [S-11][문서].</li><li><strong>외교 대신 &#39;해방 서사&#39;</strong>: 각국의 협력 여부는 퀘스트·전장 선택으로 결정되며, 최종 결전의 후일담 분기에 반영 [S-09][S-11][문서].</li><li>결전 전 기록이 지원 세력 축적에 따라 분기 — 지원이 결전 난이도·엔딩 변주로 이어진다 [S-09][문서].</li><li>명성 시스템(Renown)이 사실상 &#39;세력 평판&#39; 역할 [S-04][문서/추론].</li></ul><h2 id="_9-이벤트-내러티브" tabindex="-1">9. 이벤트/내러티브 <a class="header-anchor" href="#_9-이벤트-내러티브" aria-label="Permalink to &quot;9. 이벤트/내러티브&quot;">​</a></h2><ul><li><strong>Fevrith Archive</strong>: 스토리 진행에 따라 축적되는 세계관 기록 장치. 결전 전후 분기마다 서로 다른 기록 생성 [S-09][문서].</li><li><strong>조건부 영입이 서사 장치</strong>: 전장 대화 영입, 초반 포로 처분 선택이 수십 시간 뒤 합류에 영향 — 선택의 지연 효과 [S-11][문서].</li><li><strong>낮/밤 순환</strong>: 필드 시간대에 따른 인물 배치 변화. 바스토리아스 Nightwalk 클래스는 밤에 기동력 상승 [S-02][S-11][문서].</li><li><strong>엔딩 분기</strong>: 최종 결전에서 갈레리우스 격파 후 알레인의 처분 선택에 따라 결말 갈림 [S-09][문서].</li></ul><h2 id="_10-난이도-압박" tabindex="-1">10. 난이도/압박 <a class="header-anchor" href="#_10-난이도-압박" aria-label="Permalink to &quot;10. 난이도/압박&quot;">​</a></h2><ul><li><strong>1차 압박 = 실시간 제한시간</strong>: 평균 스테이지 3~5분. 정지 가능하지만 시계 자체가 자원 [S-01][문서].</li><li><strong>2차 압박 = 스태미나 경제</strong>: 교전마다 소모, 0이면 이동 불가. 다수 전선 운용 시 교대·휴식 설계 강요 [S-11][문서].</li><li><strong>3차 압박 = 본거지 방어/다중 경로</strong>: 거점 방어와 여러 이동 경로 선택이 동시 지휘 부담 [S-11][문서].</li><li><strong>실패의 부담</strong>: 개인 영구사망은 기본 아님. 교전 패배는 부대 후퇴로 처리되는 유연한 재시도 구조 [S-11][추론]. 난이도 모드 세부 수치는 [미확인].</li><li><strong>압박의 성격</strong>: 자원 고갈이나 로스터 소모가 아니라 <strong>시간 안의 조직 운영 실수</strong>가 난이도의 원천. 편성 실패는 교전 직전 전투력 비교 화면에서 사전 예측 가능 [S-11][문서/추론].</li></ul><h2 id="출처-목록" tabindex="-1">출처 목록 <a class="header-anchor" href="#출처-목록" aria-label="Permalink to &quot;출처 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>출처</th><th>내용</th></tr></thead><tbody><tr><td>S-01</td><td>unicornoverlord.fandom.com &quot;Battle Stages&quot;</td><td>스테이지 구조, 출격/Valor, 교전 규칙</td></tr><tr><td>S-02</td><td>〃 &quot;Classes&quot;</td><td>클래스 목록·상성·리더 효과</td></tr><tr><td>S-03</td><td>〃 &quot;Class Promotion&quot;</td><td>승격 조건·훈장 비용·AP/PP 영구 증가</td></tr><tr><td>S-04</td><td>〃 &quot;Renown&quot;</td><td>명성 등급 E~S, 누적치, 부대 확장</td></tr><tr><td>S-05</td><td>〃 &quot;Expanding Units&quot;</td><td>부대 수·인원 확장 비용·조건</td></tr><tr><td>S-06</td><td>〃 &quot;Forts&quot;</td><td>요새 기능</td></tr><tr><td>S-07</td><td>〃 &quot;Towns and Cities&quot;</td><td>5개국 마을 유형</td></tr><tr><td>S-08</td><td>〃 &quot;List of Tactics&quot;</td><td>능동/패시브/Valor 스킬 구조</td></tr><tr><td>S-09</td><td>〃 &quot;Unicorn Overlord&quot;(Fevrith Archive)</td><td>결전 분기·엔딩 변주</td></tr><tr><td>S-10</td><td>〃 &quot;Coliseum&quot;</td><td>투기장, 코인 교환</td></tr><tr><td>S-11</td><td>extended-refs-structure.md §8 (원근거: 공식 매뉴얼 S141, 한국 위키 S142, 리뷰 S143, 공식 소개 S140)</td><td>3표면, 자원 4층, 편성 규칙, 해방 구조</td></tr><tr><td>S-12</td><td>〃 &quot;Honors&quot; / &quot;Divine Shards&quot;</td><td>통화 구분</td></tr><tr><td>S-13</td><td>Steam appdetails API</td><td>무관 타이틀 반환 — 근거 미사용(조사 기록)</td></tr></tbody></table><ul><li>미확인: 난이도 모드 정확 명칭·수치, 고유 동료 전수 명단(60/64/71 집계 경계), 세부 스킬 전수표, 스태미나 세부 회복 속도.</li></ul>',49)])])}const c=r(i,[["render",d]]);export{S as __pageData,c as default};
